contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }
    function testRegression_property() public {
        uint256 totalDistributedBefore = c.totalDistributed();

        c.NETM();

        address investor = address(0x123);
        vm.deal(investor, 1 ether);
        vm.prank(investor);
        c.getTokens{value: 1 ether}();

        uint256 totalDistributedAfterFirst = c.totalDistributed();

        vm.deal(investor, 1 ether);
        vm.prank(investor);
        bool secondCallReverted = false;
        try c.getTokens{value: 1 ether}() {
            uint256 totalDistributedAfterSecond = c.totalDistributed();
            assertTrue(totalDistributedAfterSecond == totalDistributedBefore + 2 * c.value());
        } catch {
            secondCallReverted = true;
        }

        assertTrue(c.blacklist(investor) == true);
    }
}
